"""Experiment exp02c: an ensemble of v2 models, against the single v2 chosen in exp02b.

    python external/exp02c.py            # writes experiments/exp02_v2/ensemble.md and ensemble.json
    python external/exp02c.py --final    # retrains the ensemble on all 7 matches for model/v2.py

The single v2 ("mixed" in exp02b) is one LightGBM model trained on one random draw of each degraded
scenario. Here K models are trained, model k on draw k of the degradation (different ball gaps and
player drop-outs, same scenarios) and with LightGBM seed k; their probabilities are averaged and the
decoder prices are searched again, because averaged probabilities are smoother.

Same data, scenarios and protocol as exp02b; evaluation always on draw 0, so the numbers compare
directly with variants.md.

Decision rule, fixed before the run: the ensemble replaces the single v2 only if its
leave-one-match-out spellF1 on the TUNE matches (mean of the two matched scenarios) is at least
MIN_GAIN higher, and its worst case over the four degraded scenarios is not more than MIN_GAIN
lower. The HOLDOUT matches are only reported.
"""

import datetime
import json
import os
import sys
import time

import numpy as np

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)
for sub in ("", "starter", "evaluation", "model", "external"):
    sys.path.insert(0, os.path.join(ROOT, sub))

import lightgbm as lgb  # noqa: E402
import pandas as pd  # noqa: E402
import possession_metrics as pm  # noqa: E402
import degrade  # noqa: E402
import dfl  # noqa: E402
import exp02  # noqa: E402
import exp02b  # noqa: E402
import features_v2  # noqa: E402

# Params
K = 5
MIN_GAIN = 0.005
VARIANT = exp02b.VARIANTS["mixed"]
DEGRADED = exp02b.DEGRADED
OUT_JSON = os.path.join(exp02.OUT_DIR, "ensemble.json")
MODEL_DIR = os.path.join(ROOT, "model")


def fit_one(matches, k):
    xs, ys = [], []
    for m in matches:
        for s in VARIANT["train"]:
            for swap in (False, True):
                table, truth, _ = exp02.item(m, s, swap, rep=k)
                keep = np.flatnonzero(truth != pm.X)[::exp02.STRIDE]
                xs.append(table.iloc[keep][features_v2.feature_names(table)])
                ys.append(truth[keep])
    params = dict(exp02.LGB_PARAMS, seed=exp02.SEED + k)
    return lgb.train(params, lgb.Dataset(pd.concat(xs, ignore_index=True), np.concatenate(ys)),
                     num_boost_round=exp02.N_TREES)


def ensemble_probabilities(models, table, table_swap):
    return np.mean([exp02.probabilities(m, table, table_swap) for m in models], axis=0)


def cases(models, matches, scenario):
    out = []
    for m in matches:
        table, truth, runs = exp02.item(m, scenario)
        swapped = exp02.item(m, scenario, True)[0]
        out.append((ensemble_probabilities(models, table, swapped), table["half"].values, truth, runs))
    return out


def main():
    started = time.time()
    oof = {s: [] for s in DEGRADED}
    for held in exp02.TUNE:
        models = [fit_one([m for m in exp02.TUNE if m != held], k) for k in range(K)]
        for s in DEGRADED:
            oof[s] += cases(models, [held], s)
        print("fold {} ({:.0f} min so far)".format(held, (time.time() - started) / 60))
    decoder, _ = exp02.decoder_search(oof[degrade.MATCHED[0]] + oof[degrade.MATCHED[1]])
    cv = {s: exp02b.summary(oof[s], decoder) for s in DEGRADED}
    models = [fit_one(list(exp02.TUNE), k) for k in range(K)]
    holdout = {s: exp02b.summary(cases(models, exp02.HOLDOUT, s), decoder) for s in DEGRADED}

    with open(os.path.join(exp02.OUT_DIR, "variants.json"), encoding="utf-8") as handle:
        single = json.load(handle)["results"]["mixed"]
    result = {"k": K, "decoder": decoder, "cv": cv, "holdout": holdout,
              "cv_matched": float(np.mean([cv[s]["spellF1"] for s in degrade.MATCHED])),
              "cv_worst": float(min(cv[s]["spellF1"] for s in DEGRADED)),
              "holdout_matched": float(np.mean([holdout[s]["spellF1"] for s in degrade.MATCHED]))}
    adopt = (result["cv_matched"] >= single["cv_matched"] + MIN_GAIN
             and result["cv_worst"] >= single["cv_worst"] - MIN_GAIN)
    out = {"ensemble": result, "single_mixed": {k: single[k] for k in ("cv_matched", "cv_worst", "holdout_matched")},
           "adopt": adopt, "rule": "cv_matched >= single + {0} and cv_worst >= single - {0}".format(MIN_GAIN),
           "minutes": round((time.time() - started) / 60, 1),
           "written": datetime.datetime.now().replace(microsecond=0).isoformat()}
    with open(OUT_JSON, "w", encoding="utf-8") as handle:
        json.dump(out, handle, indent=1, default=float)

    lines = ["# exp02c -- ensemble of {} models (generated by external/exp02c.py)".format(K), "",
             "Rule: {} -> **{}**".format(out["rule"], "adopt the ensemble" if adopt else "keep the single v2"), "",
             "| | CV matched | CV worst | holdout matched | decoder |", "|---|---|---|---|---|",
             "| single v2 (mixed) | {:.3f} | {:.3f} | {:.3f} | {} |".format(
                 single["cv_matched"], single["cv_worst"], single["holdout_matched"], single["decoder"]),
             "| ensemble | {:.3f} | {:.3f} | {:.3f} | {} |".format(
                 result["cv_matched"], result["cv_worst"], result["holdout_matched"], decoder), "",
             "| scenario | CV spellF1 | CV macroF1 | holdout spellF1 | holdout macroF1 | holdout @0.7 | holdout transF1 | holdout pred/true |",
             "|---|---|---|---|---|---|---|---|"]
    for s in DEGRADED:
        c, h = cv[s], holdout[s]
        lines.append("| {} | {:.3f} | {:.3f} | {:.3f} | {:.3f} | {:.3f} | {:.3f} | {:.2f} |".format(
            s, c["spellF1"], c["macroF1"], h["spellF1"], h["macroF1"], h["spell@0.7"], h["transF1"], h["pred/true"]))
    with open(os.path.join(exp02.OUT_DIR, "ensemble.md"), "w", encoding="utf-8") as handle:
        handle.write("\n".join(lines) + "\n")
    print("\n".join(lines[:7]))


def final():
    """All 7 matches, K models, the decoder of the CV run; files for model/v2.py."""
    with open(OUT_JSON, encoding="utf-8") as handle:
        result = json.load(handle)["ensemble"]
    files = []
    for k in range(K):
        path = os.path.join(MODEL_DIR, "v2_lgb_{}.txt".format(k))
        fit_one(sorted(dfl.MATCHES), k).save_model(path)
        files.append(os.path.relpath(path, ROOT).replace(os.sep, "/"))
    names = features_v2.feature_names(exp02.item(exp02.TUNE[0], degrade.MATCHED[0])[0])
    with open(exp02.PARAMS_PATH, "w", encoding="utf-8") as handle:
        json.dump({"variant": "mixed, ensemble of {}".format(K), "model_files": files, "decoder": result["decoder"],
                   "relative_speeds": False, "features": names, "lgb_params": exp02.LGB_PARAMS,
                   "n_trees": exp02.N_TREES, "lgb_seeds": [exp02.SEED + k for k in range(K)],
                   "trained_on": "open DFL / IDSSE matches {} (CC BY 4.0), scenarios {}, both sides, "
                                 "degradation draws 0-{}".format(", ".join(sorted(dfl.MATCHES)),
                                                                 ", ".join(VARIANT["train"]), K - 1),
                   "decoder_tuned_on": "out-of-fold predictions on {}, matched scenarios".format(", ".join(exp02.TUNE)),
                   "written": datetime.datetime.now().replace(microsecond=0).isoformat()}, handle, indent=1)
    print("written {} and {}".format(", ".join(files), exp02.PARAMS_PATH))


if __name__ == "__main__":
    final() if "--final" in sys.argv else main()
